    toggleAllowLawsuit: function() {
        var selections = this.getSelectionModel().getSelections();

        if (selections.length > 0) {
            Ext.Msg.show({
                title: 'Tramitação de procedimentos',
                msg: 'Deseja habilitar/desabilitar tramitação de procedimentos extrajudiciais?', // CANCEL, ERROR, INFO, OK, OKCANCEL, QUESTION, WARNING, YESNO, YESNOCANCEL
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.OKCANCEL,
                scope: this,
                fn: function(btn) {
                    if (btn == 'cancel')
                        return;
                    else {
                        var pkset = selections.map(
                            function(item) {
                                return item.id;
                            }
                        );

                        var rest = this.factoryRestful();
                        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Processando...'});
                        mask.show();

                        rest.toggleAllowLawsuit(
                            pkset,
                            {
                                scope: this,
                                fn: function(message) {
                                    this.responseMessage(Ext.Msg.INFO, message);
                                    this.getStore().reload();
                                }
                            },
                            {
                                scope: this,
                                fn: function(message) {
                                    this.responseMessage(Ext.Msg.ERROR, message);
                                }
                            },
                            {
                                scope: this,
                                fn: function() {
                                    mask.hide();
                                }
                            }
                        );
                    }
                }
            });
        } else {
            Ext.Msg.show({
                title: 'this.title',
                icon: Ext.Msg.WARNING,
                buttons: Ext.Msg.OK,
                msg: 'Selecione ao menos um registro'
            });
        }
    },

